-- Foundation Studio · Snowflake execution SQL
CREATE OR REPLACE TABLE OGFS_DEMO.GOLD.fact_lab_sample AS SELECT lab_sample_key,material_key,test_method_key,'SITE_'||UPPER(site_code) site_key,CASE LOWER(business_line) WHEN 'lubricants' THEN 'BIZ_LUBRICANTS' WHEN 'fuels' THEN 'BIZ_FUELS' WHEN 'chemicals' THEN 'BIZ_CHEMICALS' END business_line_key,TO_NUMBER(TO_CHAR(completion_date,'YYYYMMDD')) date_key,DATEDIFF(day,requested_date,completion_date) turnaround_days,sample_status,source_system_count FROM OGFS_DEMO.SILVER.conformed_lab_sample;
